local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end
local hooks,timers={},{};local hookapi={Add=function(e,n,f)hooks[e.."/"..n]=f end,Remove=function(e,n)hooks[e.."/"..n]=nil end,Run=function()return true end};local timerapi={Create=function(n,d,r,f)timers[n]=f end,Remove=function(n)timers[n]=nil end};local function valid(x)return type(x)=="table"and x.valid~=false end;local function vec(x,y,z)return{x=x or 0,y=y or 0,z=z or 0}end
local function player()return{valid=true,IsPlayer=function()return true end}end;local function ent(id)local e={valid=true,id=id};function e:Remove()self.valid=false end;return e end
local copy={Entities={[30]={Class="prop_physics",Model="models/props_c17/oildrum001.mdl",Pos=vec(0,0,0),Angle=vec(0,0,0)},[10]={Class="prop_physics",Model="models/props_c17/FurnitureChair001a.mdl",Pos=vec(40,0,0),Angle=vec(0,90,0)},[20]={Class="prop_physics",Model="models/props_c17/FurnitureTable001a.mdl",Pos=vec(80,0,0),Angle=vec(0,0,0)}},Constraints={{Type="Weld",Ent1=30,Ent2=10},{Type="NoCollide",Ent1=20,Ent2=30}}}
local fail,mismatch=false,false;local last_made,last_edges=nil,nil;local dup={Copy=function()return copy end,Paste=function()local es={ent(1),ent(2),ent(3)};local cs={ent(4),ent(5)};if fail then cs[2].valid=false end;last_made,last_edges=es,cs;return es,cs end};local constraintapi={GetTable=function()return mismatch and{{Type="Weld",Ent1=30,Ent2=10}}or copy.Constraints end};local undoapi={Create=function()end,AddEntity=function()end,SetPlayer=function()end,Finish=function()return true end};local cleanupapi={Add=function()end}
local bindings;local function include()return load_submission("lua/rhenium_contraption_blueprints/blueprints.lua",bindings)end;bindings={include=include,hook=hookapi,timer=timerapi,IsValid=valid,Vector=vec,Angle=vec,NULL={},duplicator=dup,constraint=constraintapi,undo=undoapi,cleanup=cleanupapi};local S=load_submission("lua/rhenium_contraption_blueprints/server.lua",bindings);local p,root=player(),ent(9)
case("adapter installs lifecycle hooks and timer",function()S.Install({});assert(hooks["PlayerDisconnected/"..S.HookPrefix..".Disconnect"]);assert(hooks["EntityRemoved/"..S.HookPrefix..".Removed"]);assert(timers[S.TimerName])end)
case("trusted owner and root bindings authorize capture",function()assert(S.BindPlayer(p,"A"));assert(S.BindEntity(root,"root:1",1));local ok,c,d=S.Capture(p,root,"build","capture",1);assert(ok,c);assert(d.entities==3 and d.constraints==2)end)
case("public duplicator Copy and constraint table become canonical graph",function()local list=S.List(p);assert(#list==1 and type(list[1].hash)=="string")end)
case("constraint GetTable mismatch rejects capture atomically",function()mismatch=true;local ok,c=S.Capture(p,root,"mismatch","mismatch",1);assert(not ok and c=="capture_failed");assert(#S.List(p)==1);mismatch=false end)
case("unbound player and entity cannot capture or paste",function()local x=player();local ok=S.Capture(x,root,"bad","x",1);assert(not ok);ok=S.Paste(x,"build",vec(),"p",1);assert(not ok)end)
case("public Paste restores three entities and two constraints",function()local ok,c,d=S.Paste(p,"build",vec(100,0,0),"paste",1);assert(ok,c);assert(#d.entities==3 and#d.constraints==2)end)
case("partial Paste failure rolls back every live object",function()fail=true;local ok,c,d=S.Paste(p,"build",vec(200,0,0),"bad",1);assert(not ok and c=="paste_failed");assert(d.entities==0 and d.constraints==0);for _,e in ipairs(last_made)do assert(not e.valid)end;for _,e in ipairs(last_edges)do assert(not e.valid)end;fail=false end)
case("saved state restores a pasteable canonical schema",function()local state=S.Save();assert(state.schema_version==1);assert(state.owners or state.blueprints)end)
case("Install is idempotent",function()local t=timers[S.TimerName];S.Install({});assert(timers[S.TimerName]==t)end)
case("shutdown removes hooks and timer",function()S.Shutdown();S.Shutdown();for k in pairs(hooks)do if k:find("RheniumContraptionBlueprints",1,true)then error("hook leak")end end;assert(not timers[S.TimerName])end)
return{cases=cases}
